body_preview.query:
query eventSearch(
    $filter: EventSearchFilter!,
    $sort: KeywordSort,
    $first: Int,
    $after: String
) {
    eventSearch(filter: $filter, sort: $sort, first: $first, after: $after) {
        pageInfo {
            hasNextPage
            endCursor
        }
        totalCount
        edges {
            node {
                id
                title
                dateTime
                endTime
                eventType
                eventUrl
                description
                featuredEventPhoto { highResUrl }
                rsvps { totalCount }
                venue {
                    name
                    address
                    city
                    state
                    country
                    lat
                    lon
                }
                group {
                    id
                    name
                    urlname
                    timezone
                    groupPhoto { highResUrl }
                }
                feeSettings {
                    amount
                    currency
                }
            }
        }
    }
}
